ax= gca %[output:07d2e6e3]
p_ax = [50 50];
p_fig = axesToFigCoord(ax, p_ax) %[output:2fc8f299]
hold on %[output:302f5535]
plot(p_ax(1),p_ax(2),'*') %[output:302f5535]
hold off %[output:302f5535]
%%
x = [0 .1] + p_fig(1) %[output:39f16f90]
y = [0 .1] + p_fig(2) %[output:7c7ecf19]
annotation("arrow",x,y) %[output:7014af23]
